import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";var i=JSON.parse(`{"title":"Documentation maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance.md","filePath":"maintenance.md"}`),a={name:`maintenance.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="documentation-maintenance" tabindex="-1">Documentation maintenance <a class="header-anchor" href="#documentation-maintenance" aria-label="Permalink to “Documentation maintenance”">​</a></h1><p>For dependency update PRs and deferrals, see <a href="./dependabot-maintenance">Dependabot maintenance</a>.</p><h2 id="when-to-update-documentation" tabindex="-1">When to update documentation <a class="header-anchor" href="#when-to-update-documentation" aria-label="Permalink to “When to update documentation”">​</a></h2><p>Update docs <strong>in the same pull request</strong> as the behavior change when you:</p><ul><li>Add or remove Nx targets or change <code>nx.json</code> defaults</li><li>Change CI workflows (affected detection, lint commands, release steps)</li><li>Add a new plugin or theme (include <code>docs/index.md</code> and labeler entries)</li><li>Rename a plugin or theme (folder slug, Nx name, Composer name, <code>tag.yml</code> options — see <a href="./renaming-projects">Renaming a plugin or theme</a>)</li><li>Change tagging, Composer, or deployment assumptions</li></ul><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to “Ownership”">​</a></h2><ul><li><strong>Contributors</strong> are responsible for keeping package-local docs (<code>plugins/&lt;slug&gt;/docs/</code>, <code>themes/&lt;slug&gt;/docs/</code>) accurate.</li><li><strong>Maintainers / platform</strong> own root workflows, GitHub Pages, and secrets (PATs for mirrors if used).</li><li><strong>No silent TODOs</strong> — If something is blocked, add a short note with <strong>next step</strong> and <strong>who</strong> should unblock (team name or role), or create an issue and link it.</li></ul><h2 id="how-to-edit-the-docs-site" tabindex="-1">How to edit the docs site <a class="header-anchor" href="#how-to-edit-the-docs-site" aria-label="Permalink to “How to edit the docs site”">​</a></h2><ol><li><strong>Monorepo guides</strong> — Edit Markdown in <code>docs/*.md</code> (this folder).</li><li><strong>Package docs</strong> — Edit files under <code>plugins/.../docs/</code> or <code>themes/.../docs/</code>; run <code>pnpm docs:dev</code> to preview.</li><li><strong>Navigation</strong> — New top-level pages must be registered in <code>docs/.vitepress/config.mts</code> (sidebar and nav).</li><li><strong>Generated output</strong> — Never commit hand-edits under <code>docs/content/</code>; it is produced by <code>tools/sync-docs.mjs</code>.</li></ol><h2 id="review-checklist-for-doc-prs" tabindex="-1">Review checklist for doc PRs <a class="header-anchor" href="#review-checklist-for-doc-prs" aria-label="Permalink to “Review checklist for doc PRs”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> Links to GitHub paths use the correct branch or are relative where possible</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> Commands tested from a clean clone or noted if environment-specific</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> Versioning / release sections match current workflow YAML</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> No personal machine paths (for example <code>/Users/...</code>)</label></li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};